"""Read ids.txt and print the next sequential order id (base-36)."""

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def next_id(current: str) -> str:
    """Increment a 4-char base-36 id, returning the next id."""
    chars = list(current)
    for i in range(3, -1, -1):
        pos = BASE36.index(chars[i])
        if pos < 35:
            chars[i] = BASE36[pos + 1]
            break
        chars[i] = '0'
    else:
        # Overflowed all 4 digits — shouldn't happen in practice
        raise ValueError(f'Overflow incrementing {current}')
    return ''.join(chars)


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ORD-0000')
        return

    if not lines:
        print('ORD-0000')
        return

    last = lines[-1]
    if not last.startswith('ORD-') or len(last) != 8:
        print(f'Unexpected last id: {last!r}', file=sys.stderr)
        sys.exit(1)

    suffix = last[4:]
    next_suffix = next_id(suffix)
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

