"""Read ids.txt (one order id per line, most recent last) and print the next order id."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    result = 0
    for char in s:
        result = result * 36 + BASE36.index(char.upper())
    return result


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer to a base-36 string, zero-padded to the given width."""
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    while len(chars) < width:
        chars.append("0")
    return "".join(reversed(chars))


def next_order_id(last_id: str) -> str:
    """Given an order ID like 'ORD-243G', return the next one, e.g. 'ORD-243H'."""
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        raise ValueError(f"Invalid order ID format: {last_id!r}")
    suffix = last_id[4:]
    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num, width=4)
    return f"ORD-{next_suffix}"


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ERROR: ids.txt not found in current directory", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # No existing IDs; start from the first one
        print("ORD-0000")
        return

    last_id = lines[-1]
    try:
        next_id = next_order_id(last_id)
    except ValueError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)

    print(next_id)


if __name__ == "__main__":
    main()

