"""Read every .csv under data/, write consolidated all.csv."""

import glob
import os

def main():
    data_dir = "data"
    csv_files = sorted(glob.glob(os.path.join(data_dir, "*.csv")))

    if not csv_files:
        # No CSV files found — write just the header
        with open("all.csv", "w") as out:
            out.write("id,name,qty\n")
        return

    with open("all.csv", "w") as out:
        header_written = False
        for fpath in csv_files:
            with open(fpath, "r") as f:
                lines = f.readlines()
            for line in lines:
                stripped = line.strip()
                if not stripped:
                    continue
                if not header_written:
                    out.write(stripped + "\n")
                    header_written = True
                else:
                    # Skip header lines from subsequent files
                    if stripped in ("id,name,qty", "id,name,qty\r"):
                        continue
                    out.write(stripped + "\n")

if __name__ == "__main__":
    main()

