"""Read events.jsonl, remove duplicate event_ids (keep first occurrence), write deduped.jsonl."""

import json


def main():
    seen = set()
    deduped = []

    with open("events.jsonl", "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event["event_id"]
            if eid not in seen:
                seen.add(eid)
                deduped.append(event)

    with open("deduped.jsonl", "w") as f:
        for event in deduped:
            f.write(json.dumps(event) + "\n")


if __name__ == "__main__":
    main()

