#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events by event_id (keeping first occurrence),
and write the remaining events to deduped.jsonl."""

import json

def main():
    seen = set()
    with open("events.jsonl", "r") as infile, open("deduped.jsonl", "w") as outfile:
        for line in infile:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                outfile.write(json.dumps(event) + "\n")

if __name__ == "__main__":
    main()

