#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re
import sys


def report_key(filename: str):
    """Return the sort key for a report filename (its numeric sequence)."""
    match = re.match(r"report-(\d+)\.txt$", filename)
    if match is None:
        return sys.maxsize  # unknown-form filenames sort after numbered ones
    return int(match.group(1))


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")
    names = [name for name in os.listdir(reports_dir)]
    names.sort(key=report_key)
    for name in names:
        print(name)


if __name__ == "__main__":
    main()
