"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timedelta, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' timestamp from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of_unix = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of_unix, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    with open("app.log") as f:
        lines = f.readlines()

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped:
            continue
        ts = parse_timestamp(stripped)
        if ts is None:
            # Lines without a parseable timestamp are kept in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

