"""Rotate old entries from app.log to archive.log."""

import sys
import os
from datetime import datetime, timezone

def parse_timestamp(line):
    """Extract the YYYY-MM-DD HH:MM:SS timestamp from the start of a line."""
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt - __import__('datetime').timedelta(days=7)

    repo_root = os.path.dirname(os.path.abspath(__file__))
    app_path = os.path.join(repo_root, 'app.log')
    archive_path = os.path.join(repo_root, 'archive.log')

    # Read all entries from app.log
    with open(app_path, 'r') as f:
        lines = f.readlines()

    fresh = []   # entries to keep in app.log
    stale = []   # entries to move to archive.log

    for line in lines:
        if not line.strip():
            # Preserve blank lines as-is (they stay in app.log)
            fresh.append(line)
            continue
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff_dt:
            stale.append(line)
        else:
            fresh.append(line)

    # Append stale entries to archive.log (preserving order)
    if stale:
        with open(archive_path, 'a') as f:
            for line in stale:
                f.write(line if line.endswith('\n') else line + '\n')

    # Rewrite app.log with fresh entries
    with open(app_path, 'w') as f:
        for line in fresh:
            f.write(line if line.endswith('\n') else line + '\n')

if __name__ == '__main__':
    main()

