        ts_unix = ts.timestamp()
        if ts_unix < cutoff:
            old_lines.append(line_stripped)
        else:
            kept_lines.append(line_stripped)

    # Append old entries to archive.log
    if old_lines:
        with open(archive_log, 'a') as f:
            for entry in old_lines:
                f.write(entry + '\n')

    # Rewrite app.log with kept entries
    with open(app_log, 'w') as f:
        for entry in kept_lines:
            f.write(entry + '\n')

if __name__ == '__main__':
    main()

